#### Step Definition Standards

**Reusability Guidelines:**

```gherkin
# GOOD: Reusable, parameterized steps
Given I am on the "{pageName}" page
When I enter "{value}" into the "{fieldName}" field
Then I should see "{message}" in the "{elementId}" element

# BAD: Hardcoded, non-reusable steps
Given I am on the login page specifically
When I enter the password SecurePass123 into the password box
Then I should see exactly this message: "Welcome, John Doe"
```

**Step Definition Implementation Example (C#/SpecFlow):**

```csharp
[Binding]
public class NavigationSteps
{
    private readonly IWebDriver _driver;
    private readonly ScenarioContext _scenarioContext;

    public NavigationSteps(IWebDriver driver, ScenarioContext scenarioContext)
    {
        _driver = driver;
        _scenarioContext = scenarioContext;
    }

    [Given(@"I am on the ""(.*)"" page")]
    public void GivenIAmOnThePage(string pageName)
    {
        var pageUrl = PageUrlResolver.GetUrlForPage(pageName);
        _driver.Navigate().GoToUrl(pageUrl);
        _scenarioContext["CurrentPage"] = pageName;
    }

    [When(@"I enter ""(.*)"" into the ""(.*)"" field")]
    public void WhenIEnterIntoTheField(string value, string fieldName)
    {
        var element = _driver.FindElement(By.Name(fieldName));
        element.Clear();
        element.SendKeys(value);
    }

    [Then(@"I should see ""(.*)"" in the ""(.*)"" element")]
    public void ThenIShouldSeeInTheElement(string expectedText, string elementId)
    {
        var element = _driver.FindElement(By.Id(elementId));
        Assert.That(element.Text, Does.Contain(expectedText));
    }
}
```
